{
  "name": "agentshark",
  "version": "0.0.1",
  "description": "Wireshark + top for AI agents",
  "type": "module",
  "bin": {
    "agentshark": "./bin/agentshark.js"
  },
  "scripts": {
    "dev": "tsx src/cli.ts",
    "build": "tsup src/cli.ts --format esm --outDir dist --dts --clean",
    "typecheck": "tsc --noEmit",
    "smoke": "node scripts/smoke-test.js",
    "test": "node scripts/smoke-test.js",
    "attribution-prototype": "node scripts/attribution-prototype.js",
    "find-sessions": "node scripts/find-test-sessions.js",
    "timestamp-resolution": "node scripts/timestamp-resolution.js"
  },
  "dependencies": {
    "@anthropic-ai/tokenizer": "^0.0.4",
    "chokidar": "^3.6.0",
    "ink": "^5.0.1",
    "ink-text-input": "^6.0.0",
    "meow": "^13.2.0",
    "react": "^18.3.1"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "@types/react": "^18.3.0",
    "tsup": "^8.0.0",
    "tsx": "^4.0.0",
    "typescript": "^5.4.0"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/YOUR_ORG/agentshark"
  },
  "keywords": ["ai", "agents", "observability", "tui", "claude", "llm", "mcp"],
  "engines": {
    "node": ">=20"
  }
}
